.libPaths(c(Sys.getenv("WLIB"), .libPaths())); library(zujson)
t <- function(e) tryCatch(e, error = function(c) paste0("ERR[", class(c)[1], "] ", conditionMessage(c)))
cat("hour24:", t(json_write(structure(-1e-12, class = c("POSIXct","POSIXt")))), t(json_write(as.POSIXct("1970-01-01", tz = "UTC") + (0.3 - 0.1 - 0.2))), "\n")
cat("hour24 other day:", t(json_write(structure(86400 - 1e-11, class = c("POSIXct","POSIXt")))), t(json_write(structure(-86400 - 1e-11, class = c("POSIXct","POSIXt")))), "\n")
cat("ndjson lt:", gsub("\n", "|", t(json_write_ndjson(as.POSIXlt("2020-01-01", tz = "UTC")))), "\n")
cat("df NULL col:", t(json_write(structure(list(a = NULL), class = "data.frame"))), "\n")
cat("df no rownames:", t(json_write(structure(list(), names = character(0), class = "data.frame"))), "\n")
cat("df atomic:", t(json_write(structure(1:3, names = c("a","b","c"), class = "data.frame"))), "\n")
x <- "\x81\x8d"; Encoding(x) <- "latin1"; cat("latin1 C1:", t(json_write(x)), " locale:", Sys.getlocale("LC_CTYPE"), "\n")
x <- data.frame(a = integer(0)); for (i in 1:999) x <- list(x); cat("0-row df depth:", t(nchar(json_write(x))), "\n")
y <- list(); for (i in 1:999) y <- list(y); cat("same JSON from lists:", t(nchar(json_write(y))), "\n")
